// The <confetti-container> element will trigger confetti once in the viewport.
// <confetti-container data-load-on="visible" data-delay="200" data-duration="3000">
//  ...
// </confetti-container>

import poof from '@github-ui/confetti'
import {shouldReduceMotion} from './animate-on-scroll'
import {controller, attr} from '@github/catalyst'

@controller
class ConfettiContainerElement extends HTMLElement {
  @attr delay = 0
  @attr duration = 3000

  connectedCallback() {
    if (shouldReduceMotion(this)) return
    window.setTimeout(() => poof(this.duration), this.delay)
  }
}
